'use strict';
const studioNetworkLinks=document.createElement('div');studioNetworkLinks.className='studio-network-links';studioNetworkLinks.innerHTML='<a href="/agencies">Find agencies by city & field ↗</a><a href="/agency-dashboard">Agency dashboard ↗</a><a href="/network-admin" id="network-owner-link" hidden>Manage agencies ↗</a><a href="/market-ready/registrations" id="webinar-owner-link" hidden>Webinar registrations ↗</a>';document.querySelector('.studio>.section-heading').after(studioNetworkLinks);
fetch('/api/network/session').then(r=>r.ok?r.json():null).then(data=>{if(data?.canManage){document.querySelector('#network-owner-link').hidden=false;document.querySelector('#webinar-owner-link').hidden=false;}}).catch(()=>{});
const codeBox=document.createElement('details');codeBox.className='model-referral-code';codeBox.innerHTML='<summary>Have an agency referral code?</summary><label>Agency code<input id="model-agency-code" maxlength="80" placeholder="Enter your agency’s code"></label><button class="outline" type="button" id="apply-model-code">Apply code</button><p id="model-code-status" role="status"></p>';document.querySelector('#specialty-label').after(codeBox);
let studioReferralCode=new URLSearchParams(location.search).get('ref')||'',referralAttempt='';
async function connectModelCode(code){if(state.role!=='Model')return;const key=code+'|'+state.role;if(referralAttempt===key)return;referralAttempt=key;const status=document.querySelector('#model-code-status');try{const response=await fetch('/api/network/attribute',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({code,role:state.role})}),data=await response.json();if(!response.ok)throw Error(data.error||'Could not apply this code.');status.textContent=data.recorded?'Agency referral connected to your model account. Repeat sign-ins are counted once.':'Referral was not changed. This account may already have a referral or be an agency account.';}catch(error){referralAttempt='';status.textContent=error.message;}}
document.querySelector('#apply-model-code').onclick=()=>{const code=document.querySelector('#model-agency-code').value.trim();if(!code){document.querySelector('#model-code-status').textContent='Enter your agency code.';return;}studioReferralCode=code;referralAttempt='';connectModelCode(code);};
fetch('/api/network/referral-session'+(studioReferralCode?'?code='+encodeURIComponent(studioReferralCode):'')).then(r=>r.ok?r.json():null).then(data=>{if(!data?.active)return;studioReferralCode=data.code;document.querySelector('#model-agency-code').value=data.code;codeBox.open=true;connectModelCode(data.code);}).catch(()=>{});
form.elements.role.addEventListener('change',()=>{codeBox.hidden=state.role!=='Model';if(studioReferralCode)connectModelCode(studioReferralCode);});codeBox.hidden=state.role!=='Model';

const networkPreviousRender=render;render=function(){networkPreviousRender();codeBox.hidden=state.role!=="Model";};document.querySelectorAll("[data-role]").forEach(button=>button.addEventListener("click",()=>{if(studioReferralCode)connectModelCode(studioReferralCode);}));
